/* iLearn topic 10: Boolean logic (Cambridge IGCSE Computer Science 0478) */
(function(root){
  "use strict";
  var mc = root.ILQ.mc, tx = root.ILQ.tx;

  /* ---- small helpers: gate symbols drawn as SVG, truth tables generated by code ---- */
  var G = {
    AND:  { w:70, body:'<path d="M10 5H33A20 20 0 0 1 33 45H10Z"/>', ins:[[0,15,10],[0,35,10]], out:[53,70] },
    OR:   { w:70, body:'<path d="M8 5Q38 5 60 25Q38 45 8 45Q22 25 8 5Z"/>', ins:[[0,15,15],[0,35,15]], out:[60,70] },
    NOT:  { w:70, body:'<path d="M10 5L50 25L10 45Z"/><circle cx="54" cy="25" r="4"/>', ins:[[0,25,10]], out:[58,70] },
    NAND: { w:80, body:'<path d="M10 5H33A20 20 0 0 1 33 45H10Z"/><circle cx="57" cy="25" r="4"/>', ins:[[0,15,10],[0,35,10]], out:[61,80] },
    NOR:  { w:80, body:'<path d="M8 5Q38 5 60 25Q38 45 8 45Q22 25 8 5Z"/><circle cx="64" cy="25" r="4"/>', ins:[[0,15,15],[0,35,15]], out:[68,80] },
    XOR:  { w:70, body:'<path d="M12 5Q42 5 62 25Q42 45 12 45Q26 25 12 5Z"/><path d="M5 5Q19 25 5 45"/>', ins:[[0,15,15],[0,35,15]], out:[62,70] }
  };
  function gateSvg(name){
    var g = G[name], l = "";
    g.ins.forEach(function(i){ l += '<line x1="' + i[0] + '" y1="' + i[1] + '" x2="' + i[2] + '" y2="' + i[1] + '"/>'; });
    l += '<line x1="' + g.out[0] + '" y1="25" x2="' + g.out[1] + '" y2="25"/>';
    return '<svg viewBox="0 0 ' + g.w + ' 50" width="' + (g.w + 20) + '" height="64" role="img" aria-label="' + name + ' gate" style="fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round">' + g.body + l + "</svg>";
  }
  function gateCard(name){
    return '<span style="display:inline-block;text-align:center;margin:4px 10px 4px 0">' + gateSvg(name) + "<br><b>" + name + "</b></span>";
  }
  var F = {
    NOT:function(a){ return a ? 0 : 1; },
    AND:function(a,b){ return a & b; }, OR:function(a,b){ return a | b; },
    NAND:function(a,b){ return (a & b) ? 0 : 1; }, NOR:function(a,b){ return (a | b) ? 0 : 1; },
    XOR:function(a,b){ return a ^ b; }
  };
  function table(heads, rows){
    return "<table class='ln-table'><tr>" + heads.map(function(h){ return "<th>" + h + "</th>"; }).join("") + "</tr>" +
      rows.map(function(r){ return "<tr>" + r.map(function(c){ return "<td>" + c + "</td>"; }).join("") + "</tr>"; }).join("") + "</table>";
  }
  function twoIn(name){
    var rows = []; [0,1].forEach(function(a){ [0,1].forEach(function(b){ rows.push([a, b, F[name](a,b)]); }); });
    return rows;
  }
  function threeIn(fn){
    var rows = []; for(var n = 0; n < 8; n++){ var a = n >> 2 & 1, b = n >> 1 & 1, c = n & 1; rows.push([a, b, c, fn(a,b,c)]); }
    return rows;
  }
  var f1 = function(a,b,c){ return F.OR(F.AND(a,b), F.NOT(c)); };   /* X = (A AND B) OR (NOT C) */

  var LESSONS = [

  { id:"10.1", code:"10.1", title:"Logic gate symbols",
    concept:
      "<p>A <b>logic gate</b> takes one or two binary inputs (0 or 1) and gives one binary output. Circuits are drawn with standard symbols. Learn to recognise all six:</p>" +
      "<p>" + ["NOT","AND","OR","NAND","NOR","XOR"].map(gateCard).join("") + "</p>" +
      "<ul><li><b>NOT</b> is a triangle with a small circle. It is the only gate with <b>one</b> input.</li><li><b>AND</b> has a flat back and a rounded front.</li><li><b>OR</b> has a curved back and a pointed front.</li><li>A small circle on the output means the result is <b>inverted</b>: NAND is AND + circle, NOR is OR + circle.</li><li><b>XOR</b> is OR with an extra curved line at the back.</li></ul>",
    example:
      "<p>A small circle always means NOT. So:</p><table class='ln-table'><tr><th>Symbol</th><th>Means</th></tr><tr><td>AND with a circle</td><td>NOT (AND) = <b>NAND</b></td></tr><tr><td>OR with a circle</td><td>NOT (OR) = <b>NOR</b></td></tr><tr><td>OR with an extra curve</td><td>exclusive OR = <b>XOR</b></td></tr></table>",
    checks:[
      mc("Which logic gate has only one input?", "NOT", ["AND","NOR","XOR"], "NOT inverts a single input. All the other gates have two inputs."),
      mc("A gate looks like an OR gate with a small circle on its output. Which gate is it?", "NOR", ["NAND","XOR","NOT"], "OR followed by the inverting circle is a NOR gate.")
    ] },

  { id:"10.2a", code:"10.2", title:"NOT, AND and OR gates",
    concept:
      "<p>A <b>truth table</b> lists every possible combination of inputs and the output each gives.</p>" +
      "<ul><li><b>NOT</b>: the output is the opposite of the input.</li><li><b>AND</b>: the output is 1 only if <b>both</b> inputs are 1.</li><li><b>OR</b>: the output is 1 if <b>at least one</b> input is 1.</li></ul>" +
      "<div style='display:flex;gap:18px;flex-wrap:wrap'>" +
      "<div>" + table(["A","X (NOT)"], [[0,1],[1,0]]) + "</div>" +
      "<div>" + table(["A","B","X (AND)"], twoIn("AND")) + "</div>" +
      "<div>" + table(["A","B","X (OR)"], twoIn("OR")) + "</div></div>",
    example:
      "<p>Two inputs give 2 × 2 = <b>4 rows</b>; three inputs give 2 × 2 × 2 = <b>8 rows</b>. Always list the rows in binary counting order (00, 01, 10, 11).</p>" +
      "<p>Memory trick: AND = both, OR = either (or both), NOT = flip.</p>",
    checks:[
      mc("What is the output of an AND gate when the inputs are 1 and 0?", "0", ["1","10","It cannot be worked out"], "AND needs both inputs to be 1."),
      mc("What is the output of an OR gate when the inputs are 0 and 1?", "1", ["0","10","01"], "OR outputs 1 when at least one input is 1.")
    ] },

  { id:"10.2b", code:"10.2", title:"NAND, NOR and XOR gates",
    concept:
      "<ul><li><b>NAND</b>: the opposite of AND. The output is 0 only if both inputs are 1.</li><li><b>NOR</b>: the opposite of OR. The output is 1 only if both inputs are 0.</li><li><b>XOR</b> (exclusive OR, also called EOR): the output is 1 only if the inputs are <b>different</b>.</li></ul>" +
      "<div style='display:flex;gap:18px;flex-wrap:wrap'>" +
      "<div>" + table(["A","B","X (NAND)"], twoIn("NAND")) + "</div>" +
      "<div>" + table(["A","B","X (NOR)"], twoIn("NOR")) + "</div>" +
      "<div>" + table(["A","B","X (XOR)"], twoIn("XOR")) + "</div></div>",
    example:
      "<p>Compare OR and XOR on the row where both inputs are 1: OR gives <b>1</b> but XOR gives <b>0</b>. That is the only difference between them.</p>" +
      "<p>To get NAND, work out AND, then flip the answer. To get NOR, work out OR, then flip the answer.</p>",
    checks:[
      mc("What is the output of a NAND gate when both inputs are 1?", "0", ["1","2","11"], "AND gives 1, and NAND flips it to 0."),
      mc("What is the output of an XOR gate when both inputs are 1?", "0", ["1","2","It depends on the gate size"], "XOR outputs 1 only when the inputs are different.")
    ] },

  { id:"10.3a", code:"10.3a", title:"Building a circuit from a statement or expression",
    concept:
      "<p>A <b>logic expression</b> describes a circuit in words, e.g. <code>X = (A AND B) OR C</code>. To draw the circuit:</p>" +
      "<ol style='margin:0 0 12px 20px;padding:0'><li>Work out the <b>brackets first</b>; each operator in the expression is one gate.</li><li>Connect the outputs of the inner gates to the inputs of the outer gate.</li><li>Label the inputs (A, B, C) and the output (X).</li></ol>" +
      "<p>Draw exactly what is written: <b>do not simplify</b> the expression. Circuits have at most three inputs and one output.</p>",
    example:
      "<p>Statement: <i>A warning light X comes on when the engine is hot (A) AND the fan is off (B).</i></p>" +
      "<p>The fan being <b>off</b> means NOT B, so the expression is <code>X = A AND (NOT B)</code>.</p>" +
      "<p>Circuit: B goes into a <b>NOT</b> gate. The output of the NOT gate and A both go into an <b>AND</b> gate. The AND output is X. That is 2 gates.</p>",
    checks:[
      mc("How many logic gates are needed to draw <code>X = (A AND B) OR C</code>?", "2", ["1","3","4"], "One AND gate and one OR gate."),
      mc("Which expression is drawn using a NOT gate and an AND gate? ", "X = A AND (NOT B)", ["X = A OR B","X = A NOR B","X = (A AND B) OR C"], "B passes through a NOT gate before going into the AND gate.")
    ] },

  { id:"10.3b", code:"10.3b", title:"Completing a truth table",
    concept:
      "<p>To complete a truth table for a circuit or expression with three inputs:</p>" +
      "<ol style='margin:0 0 12px 20px;padding:0'><li>Write the <b>8 input rows</b> in binary order (000 to 111).</li><li>Add a working column for each inner gate or bracket.</li><li>Work out the final output row by row.</li></ol>",
    example:
      "<p>Complete the table for <code>X = (A AND B) OR (NOT C)</code>.</p>" +
      table(["A","B","C","A AND B","NOT C","X"], threeIn(f1).map(function(r){ return [r[0], r[1], r[2], F.AND(r[0],r[1]), F.NOT(r[2]), r[3]]; })) +
      "<p>The output is 1 in <b>5</b> of the 8 rows. Check by choosing a row: A=1, B=1, C=1 gives 1 OR 0 = 1.</p>",
    checks:[
      mc("How many rows does a complete truth table with three inputs have?", "8", ["3","6","9"], "2 × 2 × 2 = 8 combinations."),
      mc("For <code>X = (A AND B) OR (NOT C)</code>, what is X when A = 0, B = 1 and C = 0?", "1", ["0","2","It cannot be found"], "A AND B = 0, NOT C = 1, and 0 OR 1 = 1.")
    ] },

  { id:"10.3c", code:"10.3c", title:"Writing a logic expression",
    concept:
      "<p>To write an expression from a <b>problem statement</b>, translate the words:</p>" +
      "<table class='ln-table' style='text-align:left'><tr><th>Words</th><th>Gate</th></tr><tr><td>both / and</td><td>AND</td></tr><tr><td>either / or</td><td>OR</td></tr><tr><td>not / off / opposite</td><td>NOT</td></tr></table>" +
      "<p>To write one from a <b>circuit</b>, start at the inputs and follow each wire through the gates, writing each gate as a bracket. Use brackets so the order is clear.</p>",
    example:
      "<p>Statement: <i>A safe opens (X = 1) when the key is turned (A = 1) AND either the code is correct (B = 1) OR the fingerprint matches (C = 1).</i></p>" +
      "<p>The \"either ... or\" part is a bracket: <code>(B OR C)</code>. Joined with A: <code>X = A AND (B OR C)</code>.</p>" +
      "<p>Test it: A=1, B=0, C=1 gives 1 AND (0 OR 1) = <b>1</b>, so the safe opens.</p>",
    checks:[
      mc("An alarm X sounds when sensor A is on AND sensor B is on. Which expression is correct?", "X = A AND B", ["X = A OR B","X = NOT A","X = A NOR B"], "\"Both\" and \"and\" are written with an AND gate."),
      mc("Which expression matches a circuit where A and B go into an OR gate whose output goes into a NOT gate?", "X = NOT (A OR B)", ["X = (NOT A) OR B","X = A AND B","X = A XOR B"], "The OR comes first, then the NOT inverts the result. This is the same as a NOR gate.")
    ] }

  ];

  var TEST = {
    mcq:[
      mc("Which gate outputs 1 only when both of its inputs are 1?", "AND", ["OR","XOR","NOR"], "AND needs both inputs to be 1."),
      mc("What is the output of a NOR gate when both inputs are 0?", "1", ["0","2","00"], "OR gives 0 and NOR flips it to 1."),
      mc("What is the output of an XOR gate when the inputs are 1 and 0?", "1", ["0","10","2"], "The inputs are different, so XOR outputs 1."),
      mc("What is X when A = 1, B = 0 and C = 0 in <code>X = (A AND B) OR (NOT C)</code>?", "1", ["0","2","It cannot be found"], "A AND B = 0, NOT C = 1, so 0 OR 1 = 1."),
      mc("A truth table has three inputs. How many rows must it have?", "8", ["3","6","9"], "2 × 2 × 2 = 8.")
    ],
    typed:[
      { q:"Describe when an XOR gate outputs 1.", groups:[["different","not the same","exactly one","only one"],["output 1","outputs 1","gives 1","is 1","produces 1","high"]], need:2, model:"An XOR gate outputs 1 only when its two inputs are different (exactly one input is 1). If both inputs are the same, it outputs 0." },
      { q:"A buzzer X sounds when switch A is on and switch B is off, or when button C is pressed. Write a logic expression for X.", groups:[["x"],["not b"],["a and","and a"],["or c","c or"]], need:4, model:"X = (A AND (NOT B)) OR C" }
    ]
  };

  root.ILEARN_LESSONS = (root.ILEARN_LESSONS || []).concat(LESSONS);
  (root.ILEARN_TESTS = root.ILEARN_TESTS || {})[10] = TEST;
})(typeof window !== "undefined" ? window : this);
